import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.CleanupMode;
import org.junit.jupiter.api.io.TempDir;

class LmdbDeferredEstimatorReadinessRegressionTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:deferred-readiness:p");

	@Test
	void estimatorIsUnavailableUntilDeferredSnapshotConfiguration(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path directory = evidence.resolve("store");
		seedSnapshot(directory);
		Path snapshot = directory.resolve("join-estimator.rjes/synopsis-v8.bin");
		Path backup = evidence.resolve("original-v8-backup.bin");
		Files.copy(snapshot, backup);
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		LmdbStore store = new HeldStore(directory, config(), entered, release);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			assertTrue(entered.await(10, TimeUnit.SECONDS),
					"deferred setup must be held before synopsis configuration");
			SketchBasedJoinEstimator estimator = store.getBackingStore().getSketchBasedJoinEstimator();
			assertNotNull(estimator);
			QuadProbe probe = new QuadProbe(QuadProbe.PREDICATE, QuadProbe.OBJECT, 0L,
					QuadValueHash.hash(PREDICATE), 0L, 0L, estimator.quadSnapshotIdentity());
			assertAll("the unconfigured estimator cannot qualify an empty synopsis",
					() -> assertFalse(estimator.isReadyNonBlocking()),
					() -> assertFalse(estimator.synopsisService().probe(probe).usable()),
					() -> assertTrue(estimator.synopsisService().probePublishedCurrent(probe).isEmpty()));
			assertEquals(-1L, Files.mismatch(snapshot, backup));
		} finally {
			release.countDown();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			repository.shutDown();
		}
	}

	private static void seedSnapshot(Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), config());
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			try (var connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:deferred-readiness:s"), PREDICATE, VF.createLiteral(1));
			}
			assertTrue(store.forceFlushSketchEstimator());
			SketchBasedJoinEstimator estimator = store.getBackingStore().getSketchBasedJoinEstimator();
			estimator.stop();
			estimator.persistIfDirty();
		} finally {
			repository.shutDown();
		}
	}

	private static LmdbStoreConfig config() {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setSketchEstimatorEnabled(true)
				.setSketchEstimatorMemoryBudgetBytes(4L * 1024L * 1024L)
				.setBackgroundRawSamplingEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false);
		config.setExperimentalQueryOptimizations(true);
		return config;
	}

	private static final class HeldStore extends LmdbStore {
		private final CountDownLatch entered;
		private final CountDownLatch release;

		private HeldStore(Path directory, LmdbStoreConfig config, CountDownLatch entered, CountDownLatch release) {
			super(directory.toFile(), config);
			this.entered = entered;
			this.release = release;
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException, SailException {
			return new LmdbSailStore(directory, properties, config, sketches, null,
					(tripleDir, props, settings, values) -> new TripleStore(tripleDir, props, settings, values) {
						@Override
						void startBackgroundIndexRebuild() {
							entered.countDown();
							try {
								release.await();
							} catch (InterruptedException e) {
								Thread.currentThread().interrupt();
								return;
							}
							super.startBackgroundIndexRebuild();
						}
					});
		}
	}
}
